import json
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT))

import samples as samples_module  # noqa: E402
import spec as spec_module  # noqa: E402
from naming import OPERATION_RENAMES, snake  # noqa: E402

NOTE = (
    "Generated by codegen/make_fixtures.py. Every envelope under `published` is "
    "the response example the spec itself publishes, so the tests fail if the "
    "spec's examples stop matching the spec's schemas. The ones under "
    "`synthesized` are built from the schemas, for the operations the spec "
    "publishes no example for."
)


def examples(spec: dict) -> dict[str, dict]:
    out: dict[str, dict] = {}
    for methods in spec["paths"].values():
        for operation in methods.values():
            if not isinstance(operation, dict) or "operationId" not in operation:
                continue
            name = OPERATION_RENAMES.get(operation["operationId"], operation["operationId"])
            for code, response in operation["responses"].items():
                if not str(code).startswith("2"):
                    continue
                body = (response.get("content") or {}).get("application/json") or {}
                found = body.get("example")
                for candidate in (body.get("examples") or {}).values():
                    found = candidate.get("value")
                    break
                if found:
                    out[snake(name.replace(".", "_"))] = found
    return out


def main() -> int:
    spec_path = ROOT.parent / "spec" / "openapi.yaml"
    spec = yaml.safe_load(spec_path.read_text())
    rows = examples(spec)
    api = spec_module.load(spec_path)
    models = {
        snake(op.operation_id.replace(".", "_")): {"model": op.item, "cardinality": op.cardinality}
        for op in api.operations
    }

    model_samples = samples_module.build(api)
    built = samples_module.envelopes(api, model_samples)
    synthesized = {
        snake(name.replace(".", "_")): body
        for name, body in built.items()
        if snake(name.replace(".", "_")) not in rows
    }

    out = ROOT.parent / "fixtures.json"
    out.write_text(
        json.dumps(
            {
                "$note": NOTE,
                "operations": models,
                "envelopes": dict(sorted({**synthesized, **rows}.items())),
                "published": sorted(rows),
                "synthesized": sorted(synthesized),
                "models": dict(sorted(model_samples.items())),
            },
            indent=1,
        )
    )
    print(
        f"{out}: {len(rows)} published, {len(synthesized)} synthesized, "
        f"{len(model_samples)} models"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
